from kd_common import *
i=1
fw=foreword(i,['On a full-moon night in the Kodava month of Birchiyār, every ancestral house in Kodagu walks out into its paddy fields after dark. A girl carries a lamp, an elder carries the gun, and a man ties a bundle of leaves to the first ripe stalks, pours milk on them, and cuts a handful while everyone shouts <b>“Poli, poli, dēva!”</b>, “Grow, grow, O God!” A shot is fired into the night. The new rice is home.',
 'This is <b>Puttari</b> (Puthari, Huttari), “new rice”, the greatest festival of the Kodava year. This guide follows it from the day astrologers fix its hour at the shrine of Igguthappa, through the fourteen days of restraint, the night at Pāḍi, the night in every home, the food, the house-songs and the stick-dance on the village green.',
 'The Kodavas themselves are introduced in '+L('/kodagu/kodavas/','Part 1')+'; the god whose temple opens the festival in '+L('/kodagu/igguthappa/','Igguthappa')+'. The coast’s own new-rice festival is '+L('/tulunadu/festivals/tulu-year/','Koral Parba')+'.'],
 [('z','A gun at a harvest festival?'),('b','Kodagu is a land of farmers who were also soldiers. The gun is fired to the sky, not at anyone: a salute to the new crop.')])
gl=glance([('What','The rice harvest festival of Kodagu; Puttari means “new rice”'),('When','Kodava month of Birchiyār (Nov–Dec), on the night the moon is in Rohiṇī, near the full moon'),('Date fixed by','Astrologers of Ammangeri, at the Pāḍi Igguthappa temple, Kakkabe'),('Restraint','Fourteen days of dēva kaṭṭu (no meat, no alcohol, no harm, no felling)'),('Day 1','Pāḍi poḷd: the rite first at Igguthappa’s temple'),('Day 2','Nāḍ poḷd: the rite in every home'),('The rite','Nere kaṭṭuvo (tying the leaf bundles) and kadh eḍpo (cutting the sheaves)'),('The cry','“Poli, poli, dēva!”'),('Food','Tambuṭṭ, a sweet of roasted rice flour, banana, sesame and coconut'),('After','House-songs, the kōlāṭ stick-dance on the mand, the village gathering')],
 S('A family in Kodava dress walking to a moonlit paddy field, a girl carrying a lamp','<rect width="560" height="210" fill="#20243a"/>'+g(490,40,1.2,moon())+'<rect y="160" width="560" height="50" fill="#5a4a2a"/>'+g(440,170,1,paddy(8,180,50))+g(90,190,1,kodava_woman('#f4f1ea'))+g(108,124,.5,lamp())+g(160,190,1,kodava_man())+g(176,150,.8,gun(40))+g(230,190,1,kodava_woman('#c0392b'))+g(300,190,1,kodava_man()),'#20243a',210),
 [('z','Is it the same day everywhere?'),('b','Pāḍi goes first, the rest of Kodagu the next night. The hour is the same for everyone, fixed by the astrologers.')],'New rice <b>brought home by lamplight</b>.')
name=reading('name','NEW RICE','The name and the season',
 S('Ripe golden paddy in a terraced valley between green hills with coffee bushes',hills(560,120,'#3a7a4a')+'<rect y="150" width="560" height="60" fill="#e0c060"/>'+g(280,200,1,paddy(20,520,46))+g(60,120,1,coffee())+g(500,120,1,coffee()),'#bcd3ea',210),
 ['<b>Puttari.</b> In Kodava takk, the Kodava language, <b>put</b> is “new” and <b>ari</b> is “rice”: Puttari is the festival of the new rice. In Kannaḍa it is <b>Huttari</b>; families also say <b>Puttari poḷd</b>, “the Puttari festival”, and <b>Puttari namme</b>.',
  '<b>Birchiyār.</b> It falls in the Kodava month of Birchiyār (November–December), on the night the moon stands in <b>Rohiṇī</b>, close to the full moon.',
  '<b>The rice of the valleys.</b> Kodagu’s flat valley floors (bayal) have been paddy land for centuries, with coffee and forest on the slopes. Rice was its wealth before coffee.',
  '<b>The grandest festival.</b> Of the three great Kodava festivals, Kailpoḷd, Kāverī Saṅkramaṇa and Puttari, Puttari is the grandest and most elaborate.',
  '<b>For everyone in Kodagu.</b> Kodavas, Kodagu Gowdas and other communities of the district all keep it (see '+L('/kodagu/communities/','Part 12')+').'],
 [('z','Even families who no longer grow rice?'),('b','Yes. Many make a token field, or bring a few sheaves from a neighbour. The festival outlived the farms.')],'The year’s great night <b>belongs to the rice</b>.')
fix=reading('date','FIXING THE HOUR','Astrologers at Igguthappa’s shrine',
 S('Elders and astrologers seated before a temple with palm-leaf almanacs, offerings of rice, coconut and bananas',g(400,200,1.3,tulu_temple('#a0522d','#7a3b1f'))+''.join(g(80+k*55,205,1,person(['#f4f1ea','#1b1b1b','#f4f1ea','#1b1b1b'][k],seat=True)) for k in range(4))+g(320,205,1.1,plate()+g(0,-4,.6,banana())+g(16,-4,.6,coconut())),'#e9f2e1',215),
 ['<b>Two weeks ahead.</b> About fifteen days before the festival, the families connected with Igguthappa’s temple at Pāḍi (Kakkabe) are summoned: the Pardanda family who look after the god, the temple officials, and leading families of Pāḍi, Nelji and Perūr.',
  '<b>Offerings.</b> They bring rice, coconut, jaggery, bananas and areca nut to the shrine.',
  '<b>The astrologers.</b> Astrologers from <b>Ammangeri</b> village work out the day and the exact hour for tying the leaves, cutting the sheaves and the feast.',
  '<b>Thirteen families.</b> Recent reports describe representatives of thirteen families and the temple office-bearers meeting with the astrologers to settle the date.',
  '<b>Announced.</b> The hour is then announced on Malma hill, at the Pardanda ainmane, and at the Makki Śāstāvu temple at Bettu near Nāpoklu, and spreads across Kodagu.'],
 [('z','Why does one temple decide for the whole district?'),('b','Because Igguthappa is the god of rain and rice. His festival comes first, and his hour becomes everyone’s.')],'The god of rice <b>sets the hour</b>.')
kattu=reading('deva-kattu','DĒVA KAṬṬU','Fourteen days of restraint',
 S('A sacred grove on a hill with a small shrine; a crossed-out axe and a crossed-out meat dish',g(170,200,1.6,mountain('#3a7a4a'))+g(170,120,.5,tulu_temple())+g(150,140,.8,tree('#2f6a3a'))+g(380,140,1.2,'<path d="M0 0 v-40" stroke="#8a6a3a" stroke-width="4"/><path d="M0 -40 q18 4 20 20 q-12 -4 -20 -4z" fill="#9a9a9a"/>')+'<path d="M350 70 l60 60 M410 70 l-60 60" stroke="#c0392b" stroke-width="5"/>'+g(480,130,1.2,plate())+'<path d="M450 90 l60 60 M510 90 l-60 60" stroke="#c0392b" stroke-width="5"/>','#e9f2e1',210),
 ['<b>On Malma hill.</b> Astrologers, priests, caretakers, musicians and devotees climb <b>Malma</b> (Igguthappa Beṭṭa) and announce the hour at a shrine in a sacred grove.',
  '<b>Dēva kaṭṭu.</b> There the caretaker announces the <b>dēva kaṭṭu</b>, “the god’s binding”: fourteen days of restraint for the area of the temple.',
  '<b>What is forbidden.</b> No eating meat, no alcohol, no harming animals or people by hand or word, no pulling plants, no cutting trees. No weddings or funerals are held.',
  '<b>In the temple.</b> Only the Satyanārāyaṇa pūjā may be performed during this time.',
  '<b>Kaladcha.</b> On the day before Puttari the caretaker returns to Malma and declares the restraints lifted (kaṭṭu muripo); the temple deities are adorned, drums play, and decorated oxen dance with rice bags on their backs.'],
 [('z','No cutting even a plant?'),('b','The land is about to give its rice. For two weeks people give the land back its peace.')],'Two weeks of peace <b>before the harvest</b>.')
padi=reading('padi','PĀḌI POḶD','The first night, at Igguthappa’s temple',
 S('A temple at night with priests tying leaves to paddy and cutting sheaves, drums playing','<rect width="560" height="210" fill="#20243a"/>'+g(140,200,1.3,tulu_temple('#a0522d','#7a3b1f'))+'<rect x="260" y="170" width="300" height="40" fill="#5a4a2a"/>'+g(400,180,1,paddy(10,240,44))+g(320,196,1,person('#f4f1ea'))+g(460,196,1,person('#f4f1ea'))+g(250,190,.8,drum()),'#20243a',210),
 ['<b>Deva poḷd.</b> The first night is <b>Pāḍi poḷd</b> (also dēva poḷd): Puttari is celebrated first at the Pāḍi Igguthappa temple, Kakkabe.',
  '<b>Who.</b> The temple priest presides over the rites; the dēva takka, the hereditary caretaker, performs them.',
  '<b>The rite.</b> At the appointed hour, near the temple, the leaf bundles are tied (nere kaṭṭuvo) and the first sheaves are cut (kadh eḍpo), as in every home the next night.',
  '<b>Prasāda.</b> A festive meal is served at the temple; one year’s report times the nere kaṭṭuvo at 7.15 pm, the cutting at 8.15 pm, then the prasāda.',
  '<b>Then the land.</b> Once the god has his new rice, the rest of Kodagu may take theirs. See '+L('/kodagu/igguthappa/','Igguthappa')+'.'],
 [('z','Why does the god eat first?'),('b','Good manners and good theology. The giver of the rice receives its first sheaves.')],'The god <b>takes the first sheaves</b>.')
nere_=reading('nere','NERE KAṬṬUVO','Tying the leaf bundles',
 S('A man tying small bundles of leaves at a table; leaves of mango, jackfruit and others laid out',g(160,200,1.2,kodava_man())+''.join(g(260+k*40,190,1.4,nere()) for k in range(6))+''.join(g(260+k*50,200,.5,leaf()) for k in range(5)),'#fff3cf',210),
 ['<b>The nere.</b> A <b>nere</b> is a small bundle of leaves tied round a piece of creeper (inoli) with fibre. Neres are the blessing tied to the crop and the house.',
  '<b>Which leaves.</b> Reports name leaves of arali, mango, jackfruit, kumbaḷi and cashew; families keep their own list.',
  '<b>Who.</b> After dusk a designated man of the family ties them and lays them in a basket.',
  '<b>At the house shrine.</b> The family first prays at the <b>nellakki naḍubāḍe</b>, the sacred central hall of the ainmane with its hanging lamp (see '+L('/kodagu/ainmane/','The Ainmane')+').',
  '<b>Invoking the gods.</b> On the way to the field the family calls on its gods by name: Igguthappa, Kāverī Amma, Mahādēva, Bhadrakāḷī and the village deity.'],
 [('z','Why leaves?'),('b','Green leaves of fruit trees: the plenty of the land, tied to the grain. The crop is wished every other kind of abundance too.')],'The land’s plenty <b>tied to the grain</b>.')
field=story('field','THE NIGHT IN THE FIELD','Kadh eḍpo, cutting the first sheaves',
 strip('Three panels: a girl with a lamp leading the family to the field; a man pouring milk at the base of the paddy and tying a nere; the sheaves cut and a gun fired into the air',
  [('<rect width="144" height="190" fill="#20243a"/>'+g(40,180,.85,kodava_woman('#f4f1ea'))+g(56,114,.45,lamp())+g(96,180,.85,kodava_man())+g(124,180,.85,kodava_woman()),'#20243a'),
   ('<rect width="144" height="190" fill="#20243a"/><rect y="150" width="144" height="40" fill="#5a4a2a"/>'+g(100,160,.7,paddy(4,60,40))+g(50,180,.9,kodava_man())+g(70,130,.7,kutti())+g(90,150,.8,nere()),'#20243a'),
   ('<rect width="144" height="190" fill="#20243a"/>'+g(40,180,.85,kodava_man())+g(56,140,.9,gun(50))+g(110,40,.6,fireworks())+g(110,180,.7,paddy(3,30,40)),'#20243a')],
  ['the lamp leads','milk and the nere','“Poli, poli, dēva!”']),'Nāḍ poḷd: the second night, in every ancestral house, as described by Kodava writers and the Kodagu press.',
 ['After dusk an <b>unmarried girl</b> carrying a lit lamp on a plate leads the family to the field; women carry the plate of rice (taḷiyakki bolcha), the head of the house (paṭṭedāra) carries the gun.',
  'At the field the designated man ties a <b>nere</b> to the base of a clump of paddy and pours <b>milk</b> (and ghee) over it from the <b>kutti</b>, a sacred bamboo vessel.',
  'He cuts the sheaves with a sickle while everyone shouts <b>“Poli, poli, dēva!”</b>, “Increase, increase, O God!”',
  'A <b>gun</b> is fired into the air (often three times) and crackers burst.',
  'An odd number of sheaves, <b>five, seven, nine or eleven</b>, is cut and carried home in procession, still to the cry of “Poli, poli, dēva!”'],
 [('z','Why an odd number?'),('b','Odd numbers are auspicious in many South Indian rites: never complete, always more to come.')],'A cry for increase <b>and a shot at the stars</b>.')
home=reading('home','THE SHEAVES COME HOME','Tied to the house',
 S('An ancestral house with sheaves of paddy and leaf bundles tied over the door, a lamp in the hall',g(280,205,1.6,ainmane())+g(280,120,1,paddy(4,40,30))+g(200,150,.8,nere())+g(360,150,.8,nere())+g(280,170,.6,hanging_lamp()),'#fff3cf',215),
 ['<b>To the nellakki.</b> The sheaves are carried to the house’s prayer place, the nellakki naḍubāḍe, and offered.',
  '<b>Tied everywhere.</b> Sheaves and neres are tied at the front of the house, the kitchen, the prayer place, the granary and the cow shed, and on farm tools.',
  '<b>Dhānya Lakṣmī.</b> Families describe the moment as welcoming <b>Dhānya Lakṣmī</b>, the goddess of grain, into the house.',
  '<b>The new rice is cooked.</b> A few grains of the new paddy are husked and added to the festive food.',
  '<b>Crackers.</b> The night ends with firecrackers and a family feast.'],
 [('z','Rice tied to the cow shed?'),('b','Every part of the farm that helped grow it gets its share of the blessing, the cows most of all.')],'The grain goddess <b>enters the house</b>.')
food=cards('food','THE PUTTARI TABLE','Tambuṭṭ and the feast',
 fig_row('A bowl of tambuṭṭ, bananas, a coconut, sesame and a plate of rice',[(plate()+'<ellipse cy="-8" rx="18" ry="8" fill="#c98a5a"/>',1.4),(banana(),1.4),(coconut(),1.3),(lotus('#e0a800','#b8860b'),1.2),(lamp(),1.3)],['tambuṭṭ','banana','coconut','new rice','the lamp'],gy=150),
 [('🍮','Tambuṭṭ','The Puttari sweet: roasted rice flour mixed with ripe mashed banana, sesame, grated coconut, jaggery or sugar and ghee, with cardamom.'),('🍃','On a leaf','Served on a peepal leaf before the nellakki, shared among the family.'),('🥔','Kalinji','A boiled tuber is also served in some families.'),('🍚','New rice','A little of the new rice goes into the meal.'),('🍖','The feast','After the restraint of the season, a great family feast; meat dishes return on the following days in most homes.'),('👪','Together','Families living far away come home to the ainmane for this meal.')],
 None,'Rice, banana and sesame: <b>the taste of Puttari</b>.',
 intro='Recipes vary by family; these are the dishes most often named in reports of the festival.')
after=reading('after','AFTER THE NIGHT','House-songs and the hunt',
 S('Four folk singers with small hourglass drums standing at the door of a house',g(400,205,1.3,ainmane(160))+''.join(g(80+k*60,205,1,person('#f4f1ea'))+g(90+k*60,150,.6,dudi()) for k in range(4)),'#fff3cf',215),
 ['<b>Mane pāḍo.</b> On the day after Nāḍ Puttari, four folk singers carry small hourglass drums (<b>duḍi</b>) and visit each house; two of them sing verses praising the family. (House-singing.)',
  '<b>Gifts.</b> The household gives them rice and gifts in return.',
  '<b>The hunt.</b> Traditionally, at a time fixed by the astrologer, the village youth set out on a hunt after the festival, with rules for dividing the game. (Old custom; hunting is now restricted by law.)',
  '<b>Eleven days once.</b> Puttari is said to have run for eleven days in the past; today it is kept over a few days.',
  '<b>Visits.</b> Families visit relatives and neighbours with tambuṭṭ.'],
 [('z','Singers who praise each family?'),('b','A village’s memory in song: who your ancestors were, what your house has done. It binds the village together.')],'A village <b>sings its families</b>.')
kola=reading('kolat','THE KŌLĀṬ','The stick-dance under the moon',
 S('Men in black kupyas and white turbans dancing in a circle striking short sticks, drummers and a horn player',''.join(g(70+k*70,200,1.1,kola_dancer('#1b1b1b',k%2==1)) for k in range(7))+g(520,190,.8,drum()),'#e3eaf3',210),
 ['<b>Practised in the moonlight.</b> For eight evenings before Puttari, village men practise the <b>Puttari kōlāṭ</b> (stick-dance) in the moonlight on the <b>mand</b>, the village green.',
  '<b>After the festival.</b> A few days after Puttari the village gathers on the mand: horns and large drums play while men dance in circles, striking short rattan sticks (<b>kōl</b>) in rhythm.',
  '<b>Invocations.</b> At the mands the names of Aiyappa, Mahādēva and Bhagavatī are invoked.',
  '<b>Ūrorme.</b> Then comes the <b>ūrorme</b>, the village gathering, which closes the festival season.',
  '<b>More dances.</b> Bōlakāṭ, Ummattāṭ and Kombāṭ, and the mand itself, are in '+L('/kodagu/mand-and-dances/','Part 6')+'.'],
 [('z','Why sticks?'),('b','Rhythm you can see and hear. Every strike lands together, or the whole circle hears the mistake.')],'Sticks striking <b>in one rhythm</b>.')
today=reading('today','PUTTARI TODAY','In Kodagu, Mysuru and Bengaluru',
 S('A city hall courtyard with a small symbolic paddy plot and families in Kodava dress cutting sheaves',g(280,200,1,'<rect x="-120" y="-40" width="240" height="40" fill="#5a4a2a"/>')+g(280,180,1,paddy(10,220,36))+g(120,205,1,kodava_man())+g(440,205,1,kodava_woman())+g(500,205,1,kodava_man()),'#e3eaf3',215),
 ['<b>Away from the fields.</b> Many Kodavas now live outside Kodagu. Families in a region gather and celebrate together, keeping the old order.',
  '<b>Samājas.</b> The Kodava Samājas of Mysuru, Bengaluru and other cities hold “Puttari Namme”: a token paddy field is made on the grounds, the leaves are tied and the sheaves cut at the astrologer’s hour, and tambuṭṭ is shared.',
  '<b>Gowda Samājas.</b> The Kodagu Gowda Samājas celebrate it with equal fervour.',
  '<b>Temples.</b> Temples across Kodagu, such as the Mṛtyuñjaya temple at Baḍagarakēri, hold collective Puttari for their villages.',
  '<b>Why it lasts.</b> A festival of home, family and land is what people far from home miss most.'],
 [('z','A paddy field in a city school?'),('b','A few square metres of rice, grown for one night. That is how much the night matters.')],'A paddy field <b>for one night in the city</b>.')
endp=end(i,['<b>Name.</b> Puttari, “new rice”, in Birchiyār, on the night of Rohiṇī.','<b>Hour.</b> Fixed by Ammangeri’s astrologers at Pāḍi Igguthappa; fourteen days of restraint.','<b>Night one.</b> Pāḍi poḷd at the god’s temple.','<b>Night two.</b> In every home: lamp, nere, milk, sickle, gun, “Poli, poli, dēva!”','<b>After.</b> Tambuṭṭ, house-songs, the kōlāṭ and the village gathering.'],
 'Part 3 turns to Kailpoḷd, the festival of arms.','The night of the new rice')
src=sources([('Puttari:','Deccan Herald, “Revering nature, culture” (preparation, astrologers of Ammangeri, Malma, dēva kaṭṭu, Kaladcha, Pāḍi poḷd and Nāḍ poḷd, nere and kadh rite, tambuṭṭ, mane pāḍo, kōlāṭ); Deccan Herald on the mands (kōlāṭ practice, invocations, ūrorme) and on Puthari (paṭṭedāra, odd sheaves, kutti); kodavaclan.com (procession, invocations, milk and ghee); Deccan Herald (leaves used in nere kaṭṭuva); Coorg Tourism Info (odd numbers, hunt); Star of Mysore reports 2019–2025 (date-fixing by thirteen families, timings, tambuṭṭ recipe, kalinji, eleven days in the past, Samāja celebrations, Gowda Samāja, Baḍagarakēri).')],
 'spellings of Kodava words vary; the exact order of the nere and kadh rites differs between families; the hunt is described as past custom.','Kodava terms in simple romanisation with IAST marks.')
finish(i,'PART 2 OF 12 · NEW RICE · NERE · POLI POLI DĒVA',covart('A Kodava man cutting paddy at night with a lamp-bearing girl beside him and a gun fired to the sky','<rect width="440" height="196" fill="#20243a"/>'+g(390,40,1,moon())+'<rect y="150" width="440" height="46" fill="#5a4a2a"/>'+g(320,170,1,paddy(8,160,44))+g(90,186,1,kodava_woman('#f4f1ea'))+g(106,120,.5,lamp())+g(170,186,1,kodava_man())+g(186,140,.8,gun(50))+g(230,40,.7,fireworks())),'The night of the new rice',
 '<b>Puttari</b>, Kodagu’s festival of new rice: the <b>hour fixed</b> at Igguthappa’s temple, the <b>restraint</b>, the <b>night in the field</b> with lamp, milk and gun, and the <b>songs and dances</b> after.',
 'Puttari (Puthari, Huttari) explained and illustrated: Kodagu’s new-rice festival in Birchiyār, date-fixing at Pāḍi Igguthappa, dēva kaṭṭu, Pāḍi poḷd and Nāḍ poḷd, nere kaṭṭuvo and kadh eḍpo, “Poli poli dēva”, tambuṭṭ, house-songs and the kōlāṭ.',
 [fw,gl,name,fix,kattu,padi,nere_,field,home,food,after,kola,today,endp,src])
